mapper.select:
select 
from 财务原始数据
where 数据ID = #{dataId,jdbcType=BIGINT}

mapper.update:
update 财务原始数据
公司ID = #{companyId,jdbcType=INTEGER}, 财年 = #{fiscalYear,jdbcType=SMALLINT}, 报告期 = #{reportPeriod,jdbcType=VARCHAR}, 项目ID = #{itemId,jdbcType=INTEGER}, 金额 = #{amount,jdbcType=DECIMAL}, 数据来源 = #{source,jdbcType=VARCHAR}, 入库时间 = #{createTime,jdbcType=TIMESTAMP},
where 数据ID = #{dataId,jdbcType=BIGINT}

mapper.select:
select r.项目编码, r.项目名称, r.所属报表, r.单位, d.金额
from 财务原始数据 d
join 报表项目 r on d.项目ID = r.项目ID
where d.公司ID = #{companyId,jdbcType=INTEGER}
  and d.财年 = #{fiscalYear,jdbcType=SMALLINT}
  and d.报告期 = #{reportPeriod,jdbcType=VARCHAR}
order by r.显示顺序

mapper.delete:
delete from 财务原始数据
where 公司ID = #{companyId,jdbcType=INTEGER}
  and 财年 = #{fiscalYear,jdbcType=SMALLINT}
  and 报告期 = #{reportPeriod,jdbcType=VARCHAR}
